command.text:
param([ValidateSet('build','test','throughput','q7169','q8192')][string]$Action='build')
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$repo='D:\projects\AIMA-public-absolute-bound-gdn-20260919-r1';$seed='D:\projects\AIMA-public-prefill-scratch-reuse-20260919-r1';$sha='29d389b584ca76fdefc359a946b198d7eb478c1f';$bundle='D:\projects\absolute-bound-gdn-29d389b.bundle'
function Verify-File([string]$Path,[string]$Hash){if((Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $Hash){throw ('Changed input: '+$Path)}}
Verify-File $bundle '90c9e43ab316c24eac1c07b5e6b8b19682b9c038e5927e903b60acfb24f8f5ec'
if(-not (Test-Path $repo)){
 & git -C $seed fetch $bundle HEAD;if($LASTEXITCODE -ne 0){throw 'Fetch failed'}
 & git -C $seed worktree add --detach $repo $sha;if($LASTEXITCODE -ne 0){throw 'Worktree creation failed'}
}
if((& git -C $repo rev-parse HEAD).Trim() -ne $sha -or @(& git -C $repo status --porcelain).Count -ne 0){throw 'Source mismatch'}
$build=Join-Path $repo 'build\absolute-bound-gdn';$null=New-Item -ItemType Directory -Path $build -Force
$source=Join-Path $repo 'tests\native\absolute_bound_gdn_selftest.cpp';$exe=Join-Path $build 'absolute-bound-gdn.exe';$provenance=Join-Path $build 'build-provenance.json'
$sourceManifestPath='D:\projects\absolute-bound-gdn-native-source-r1.json'
$manifest=[IO.File]::ReadAllText($sourceManifestPath)|ConvertFrom-Json
if($manifest.source_commit -ne $sha){throw 'Manifest commit mismatch'}
$sourceInputs=@($manifest.source_sha256.psobject.Properties|ForEach-Object {
 $path=Join-Path $repo $_.Name;Verify-File $path $_.Value
 @{file=$path;sha256=$_.Value}
})
$spec=[ordered]@{executable='';arguments=@();working_directory=$repo;repo_commit=$sha;command_file=$PSCommandPath;command_file_sha256=(Get-FileHash $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();source_inputs=$sourceInputs;model='none; generated complete GDN WU, recurrent state and output components with the original SM121 exponential table';model_loaded=$false;inference_acceptance=$false;performance_acceptance=$false;product_dispatch_changed=$false;purpose='Compare retained paired scores and scalar WU/shared-arena state/output against consumer-certified omission of W/H dots, then Q/H dots too. Both BF16 residual consumers or the complete output consumer must agree across an absolute norm envelope. Rejected cells enter a bounded shared queue for the unchanged scalar dot. Original K64 updates, FP32 states and checkpoints remain unchanged. Seven generated families and eight boundary shapes check every intermediate, ownership and independent integer CPU dots; original GB10 q7169 checks full captured output/state. q8192 repeats1024 captured rows and remains a component extension. Runtime dispatch, tolerances and process/host guards are unchanged.'}
$previousPath='D:\projects\AIMA-public-compact-suffix-query-20260919-r2\build\scratch-compact-query-prefix256k-long-prefix262144-suffix1024-out512-mode1-r1\run-record.json'
$previous=[IO.File]::ReadAllText($previousPath)|ConvertFrom-Json
if(-not $previous.host_checks_pass -or @($previous.after_processes).Count -or @($previous.host_checks.psobject.Properties|Where-Object {-not $_.Value}).Count){throw 'Previous model cleanup incomplete'}
$spec.previous_model_run_sha256=(Get-FileHash $previousPath -Algorithm SHA256).Hash.ToLowerInvariant()
$spec.source_manifest_sha256=(Get-FileHash $sourceManifestPath -Algorithm SHA256).Hash.ToLowerInvariant()
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
if($Action -eq 'build'){
 $spec.executable='C:\Program Files\AMD\ROCm\7.1\bin\hipcc.exe'
 $spec.arguments=@('-std=c++17','-O3','-DQRT_SM121_DPP_REDUCTION=1','-DQRT_SM121_COMPACT_NORMALIZE=1','--offload-arch=gfx1151',$source,'-o',$exe);$timeout=180
}else{
 $meta=[IO.File]::ReadAllText($provenance)|ConvertFrom-Json
 if($meta.repo_commit -ne $sha){throw 'Build commit mismatch'}
 Verify-File $exe $meta.executable.sha256
 foreach($file in $meta.source_inputs){Verify-File $file.file $file.sha256}
 $spec.build_provenance_sha256=(Get-FileHash $provenance -Algorithm SHA256).Hash.ToLowerInvariant()
 $table='D:\projects\sm121-exp2-negative-f490940d.bin'
 Verify-File $table 'f490940df2bd80421159a96424c3e922330b7ca120d5ae7b629a973b9183730b'
 $spec.table=@{path=$table;bytes=(Get-Item $table).Length;sha256='f490940df2bd80421159a96424c3e922330b7ca120d5ae7b629a973b9183730b'}
 if($Action -ne 'test'){
  $priorPath=Join-Path $repo 'build\absolute-bound-gdn-test-r1\run-record.json';$prior=[IO.File]::ReadAllText($priorPath)|ConvertFrom-Json
  if($prior.reason -ne 'completed' -or $prior.exit_code -ne 0 -or -not $prior.host_checks_pass){throw 'Safety prerequisite failed'}
  $spec.safety_run_sha256=(Get-FileHash $priorPath -Algorithm SHA256).Hash.ToLowerInvariant()
 }
 $spec.executable=$exe;$spec.arguments=@($table,$(if($Action -eq 'test'){'safety'}else{$Action}));$timeout=300
 if($Action.StartsWith('q')){
  $capture='D:\projects\sparse-group-gdn-capture-20260918-r1'
  $manifestPath=Join-Path $capture 'manifest.json';Verify-File $manifestPath '57321dfcb495c5555fbde96cce5fe31038590f3be22c9f72b72bc80d1d5d791a'
  $manifest=[IO.File]::ReadAllText($manifestPath)|ConvertFrom-Json
  foreach($input in $manifest.files){$inputPath=Join-Path $capture $input.file;Verify-File $inputPath $input.sha256;if((Get-Item $inputPath).Length -ne $input.bytes){throw 'Capture span mismatch'}}
  $spec.capture=$manifest;$spec.capture_manifest_sha256='57321dfcb495c5555fbde96cce5fe31038590f3be22c9f72b72bc80d1d5d791a';$spec.model='D:\models\Qwen3.6-35B-A3B; original GB10 layer0 GDN capture';$spec.arguments+=@($capture)
  if($Action -eq 'q8192'){
   $priorPath=Join-Path $repo 'build\absolute-bound-gdn-q7169-r1\run-record.json';$prior=[IO.File]::ReadAllText($priorPath)|ConvertFrom-Json
   if($prior.reason -ne 'completed' -or $prior.exit_code -ne 0 -or -not $prior.host_checks_pass){throw 'Original capture prerequisite failed'}
   $spec.original_capture_run_sha256=(Get-FileHash $priorPath -Algorithm SHA256).Hash.ToLowerInvariant()
  }
 }
}
$out=Join-Path $repo ('build\absolute-bound-gdn-'+$Action+'-r1');$specPath=Join-Path $build ($Action+'-spec-r1.json')
if((Test-Path $out) -or (Test-Path $specPath)){throw 'Evidence already exists'}
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
& (Join-Path $repo 'scripts\baiying_guarded_inference.ps1') -SpecPath $specPath -OutDir $out -TimeoutSeconds $timeout|Out-Null
$r=[IO.File]::ReadAllText((Join-Path $out 'run-record.json'))|ConvertFrom-Json
$r|Select-Object reason,exit_code,wall_ms,host_checks|ConvertTo-Json -Depth 5
foreach($name in @('product.stdout.jsonl','product.stderr.log')){Get-Content (Join-Path $out $name) -Tail 8|ForEach-Object {$_.Substring(0,[Math]::Min(2000,$_.Length))}}
if($r.reason -ne 'completed' -or $r.exit_code -ne 0 -or -not $r.host_checks_pass){throw 'Native diagnostic action failed'}
if($Action -eq 'build'){
 $meta=[ordered]@{host=[Environment]::MachineName;repo_commit=$sha;source_inputs=$sourceInputs;command_file=$PSCommandPath;command_file_sha256=$spec.command_file_sha256;compiler=$spec.executable;arguments=$spec.arguments;run_record_sha256=(Get-FileHash (Join-Path $out 'run-record.json') -Algorithm SHA256).Hash.ToLowerInvariant();executable=@{file=$exe;bytes=(Get-Item $exe).Length;sha256=(Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant()}}
 [IO.File]::WriteAllText($provenance,($meta|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
}else{
 $reports=@([IO.File]::ReadAllLines((Join-Path $out 'product.stdout.jsonl'))|Where-Object {$_.StartsWith('{')}|ForEach-Object {$_|ConvertFrom-Json})
 $cases=@($reports|Where-Object {$_.kind -eq 'absolute_bound_gdn_component'})
 $expected=if($Action -eq 'test'){336}elseif($Action -eq 'throughput'){12}else{6};$measured=if($Action -eq 'test'){0}else{3}
 if($cases.Count -ne $expected){throw 'Incomplete prepared GDN comparisons'}
 foreach($r in $cases){
  if($r.raw_bit_mismatches -ne 0 -or -not $r.all_attempts_verified -or -not $r.redzones_pass -or -not $r.immutable_nonaliased_inputs -or -not $r.intermediate_and_alias_ownership_checked -or $r.measured_attempts -ne $measured){throw 'Prepared GDN numerical comparison failed'}
  if($Action -ne 'test' -and (($Action -ne 'q7169' -and $r.tokens -ne 8192) -or $r.samples_ms.Count -ne 3 -or $r.complete_score_wu_state_output_ms -le 0)){throw 'Incomplete full-shape timing'}
  if($Action.StartsWith('q') -and (-not $r.captured_inputs -or $r.gb10_output_cells -ne $(if($Action -eq 'q7169'){29364224}else{29360128}))){throw 'Incomplete original GB10 capture boundary'}
  if($r.score_cells -ne ($r.tokens*2048) -or -not $r.output_arena_reuse -or $r.absolute_bound_state -ne ($r.variant -ne 0) -or $r.absolute_bound_output -ne ($r.variant -eq 2)){throw 'Score span or absolute bound route selection mismatch'}
  if($r.intermediate_host_synchronization -or $r.segment_tokens -ne 1024 -or $r.segments -ne [Math]::Ceiling($r.tokens/1024.0)){throw 'Segment contract failed'}
 }

}
